import{_ as t,o as a,c as o,a3 as n}from"./chunks/framework.DMtjdCb-.js";const r="/help/assets/windows-release.DqdtVb9U.png",g=JSON.parse('{"title":"1. 电脑部署","description":"","frontmatter":{},"headers":[],"relativePath":"zh-Hans/desktop.md","filePath":"zh-Hans/desktop.md"}'),s={name:"zh-Hans/desktop.md"};function i(l,e,d,c,h,p){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="_1-电脑部署" tabindex="-1">1. 电脑部署 <a class="header-anchor" href="#_1-电脑部署" aria-label="Permalink to &quot;1. 电脑部署&quot;">​</a></h1><p>本章完成后，可以在浏览器打开 AnimeMachine。下载动画时再连接 qBittorrent 或 Ani-RSS；播放电脑上已有的动画可直接<a href="./collections.html">添加媒体目录</a>。</p><h2 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows {#windows}&quot;">​</a></h2><ol><li>打开 <a href="https://github.com/kyupi-git/animemachine/releases/latest" target="_blank" rel="noreferrer">Releases</a>，展开 <strong>Assets</strong>。</li><li>下载名称以 <code>release-windows.zip</code> 结尾的文件。</li><li>右键 ZIP，选择 <strong>全部解压缩</strong>，解压到固定目录，例如 <code>D:\\AnimeMachine</code>。</li><li>打开解压后的文件夹，双击 <strong><code>AnimeMachine.cmd</code></strong>，保留启动窗口。</li><li>在浏览器打开 <strong><a href="http://localhost:8787" target="_blank" rel="noreferrer">http://localhost:8787</a></strong>。</li></ol><p><img src="'+r+'" alt="Windows 启动窗口、解压后的目录与首页" loading="lazy"></p><p><strong>完成标志：</strong> 出现 AnimeMachine 登录页面。用户名和初始密码位于启动窗口；接下来阅读<a href="./first-use.html">首次打开</a>。</p><p>发布包包含运行环境。后续仍从同一目录双击 <code>AnimeMachine.cmd</code> 启动；关闭启动窗口即可停止。</p><h2 id="macos-linux" tabindex="-1">macOS / Linux <a class="header-anchor" href="#macos-linux" aria-label="Permalink to &quot;macOS / Linux {#macos-linux}&quot;">​</a></h2><ol><li>安装 <a href="https://www.python.org/downloads/" target="_blank" rel="noreferrer">Python 3.11 或更新版本</a>。</li><li>在 <a href="https://github.com/kyupi-git/animemachine/releases/latest" target="_blank" rel="noreferrer">Releases</a> 下载与系统和处理器对应的发布包并解压。</li><li>macOS 双击 <strong><code>AnimeMachine-macOS.command</code></strong>。Linux 在解压目录打开终端，运行：</li></ol><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./AnimeMachine-Linux.sh</span></span></code></pre></div><ol start="4"><li>等待启动完成，打开 <strong><a href="http://localhost:8787" target="_blank" rel="noreferrer">http://localhost:8787</a></strong>，按<a href="./first-use.html">首次打开</a>登录。</li></ol><table tabindex="0"><thead><tr><th>处理器</th><th>发布包中的标识</th></tr></thead><tbody><tr><td>Intel / AMD</td><td><code>x86_64</code></td></tr><tr><td>Apple 芯片、ARM 电脑</td><td><code>arm64</code> 或 <code>aarch64</code></td></tr></tbody></table><p>启动器会安装所需组件。保留终端窗口，按 <code>Ctrl+C</code> 停止。遇到执行权限提示时，Linux 运行 <code>chmod +x AnimeMachine-Linux.sh</code>，macOS 运行 <code>chmod +x AnimeMachine-macOS.command</code>，再重新启动。</p><h2 id="从其它设备访问" tabindex="-1">从其它设备访问 <a class="header-anchor" href="#从其它设备访问" aria-label="Permalink to &quot;从其它设备访问&quot;">​</a></h2><p>电脑与手机连接同一局域网时，手机浏览器使用启动窗口列出的 <strong>LAN URL</strong>，例如 <code>http://192.168.1.20:8787</code>。<code>localhost</code> 指正在操作的设备，在手机中使用它会访问手机自身。</p><h2 id="本步常见问题" tabindex="-1">本步常见问题 <a class="header-anchor" href="#本步常见问题" aria-label="Permalink to &quot;本步常见问题&quot;">​</a></h2><ul><li><strong>找不到启动文件：</strong> 先完整解压 ZIP，再进入解压后的目录；在资源管理器中启用“显示文件扩展名”可核对文件名。</li><li><strong>网页打不开：</strong> 检查启动窗口是否仍在运行，按窗口实际显示的端口访问。<a href="./troubleshooting.html#open-page">连接问题</a>提供后续检查顺序。</li><li><strong>想更换安装目录：</strong> 停止程序后移动整个目录，保留 <code>config.json</code> 和 <code>data</code>，再从新目录启动。</li></ul>',17)])])}const u=t(s,[["render",i]]);export{g as __pageData,u as default};
